$(".modal-result").on("submit", function(event) {
    event.preventDefault(); 
    console.log("Form submitted"); 

    let student_id = $("#student_id").val();
    let id = $("#updateid").val();
    let midterm = $("#midterm").val();
    let coursework = $("#coursework").val();
    let final = $("#final").val();
    let reexam = $("#reexam").val(); 
    let subject_id = $("#subject_id").val(); 

  
    let btnaction = "Insert"; 
    let sendingData = {};

    if (btnaction === "Insert") {
        sendingData = {
            student_id: student_id,
            midterm: midterm,
            coursework: coursework,
            final: final,
            reexam: reexam,
            subject_id: subject_id,
            action: "register_result"
        };
    } else if (btnaction === "Update") {
        sendingData = {
            student_id: student_id,
            midterm: midterm,
            coursework: coursework,
            final: final,
            reexam: reexam,
            subject_id: subject_id,
            result_id: id, 
            action: "Update_result"
        };
    } else {
        console.error(" action type");
        return;
    }

    
    $.ajax({
        method: "POST",
        dataType: "JSON",
        url: "../Api/cre_result.php",
        data: sendingData,
        success: function(data) {
            let status = data.status;
            let response = data.data;

            if (status) {
                Swal.fire({
                    title: response,
                    icon: "success"
                });
                console.log("Success:", response);
            } else {
                Swal.fire({
                    title: "Error",
                    text: response,
                    icon: "error"
                });
            }
        },
        error: function(xhr, status, error) {
            console.error("AJAX Error:", error);
        }
    });
});






























