$('#class_id').on('change', function () {
    const selectedClass = $(this).val();
    
    if (selectedClass  ) {
        const className = $(this).find(':selected').text();
        $('#selectedClassName').text(className);   
    }
   
});


$('#semester_id').on('change', function () {
    const selectedClass = $(this).val();
    
    if (selectedClass  ) {
        const className = $(this).find(':selected').text();
        // $('#selectedClassName').text(className);
        $('#selectedmester').text(className);
      
        $(".modal-result").toggle();

        
    }
   
});



